48	/** Reads markdown content from contentDir, converts it to HTML, and writes the site to outputDir. */
49	export function build(options: BuildOptions): BuildResult {
50	  const { contentDir, outputDir } = options;
51	  const siteTitle = options.siteTitle ?? 'My Site';
52	  const templatesDir = options.templatesDir ?? './templates';
53	
54	  if (!fs.existsSync(contentDir) || !fs.statSync(contentDir).isDirectory()) {
55	    throw new Error(`Content directory not found: ${contentDir}`);
56	  }
57	
58	  const markdownFiles = findMarkdownFiles(contentDir).sort();
59	
60	  const pages: Page[] = markdownFiles.map((filePath) => {
61	    const raw = fs.readFileSync(filePath, 'utf-8');
62	    const slug = toSlug(contentDir, filePath);
63	    const { frontmatter, contentHtml } = parseMarkdown(raw, titleFromSlug(slug));
64	    return { slug, frontmatter, contentHtml, sourcePath: filePath };
65	  });
66	
67	  pages.sort(comparePages);
68	
69	  fs.rmSync(outputDir, { recursive: true, force: true });
70	  fs.mkdirSync(outputDir, { recursive: true });
71	
72	  const outputFiles: string[] = [];
73	
74	  for (const page of pages) {
75	    const outputPath = path.join(outputDir, `${page.slug}.html`);
76	    fs.mkdirSync(path.dirname(outputPath), { recursive: true });
77	    fs.writeFileSync(outputPath, renderPageHtml(page, { templatesDir, siteTitle }), 'utf-8');
78	    outputFiles.push(outputPath);
79	  }
80	
81	  const indexPath = path.join(outputDir, 'index.html');
82	  fs.writeFileSync(indexPath, renderIndexHtml(pages, siteTitle, { templatesDir }), 'utf-8');
83	  outputFiles.push(indexPath);
84	
85	  const stylesheetPath = path.join(outputDir, 'style.css');
86	  fs.writeFileSync(stylesheetPath, DEFAULT_STYLESHEET, 'utf-8');
87	  outputFiles.push(stylesheetPath);
88	
89	  return { pages, outputFiles };
90	}
