7	function normalizeDate(value: unknown): string | undefined {
8	  if (value instanceof Date) {
9	    return value.toISOString().slice(0, 10);
10	  }
11	  if (typeof value === 'string' && value.trim().length > 0) {
12	    return value.trim();
13	  }
14	  return undefined;
15	}
16	
17	function normalizeOptionalString(value: unknown): string | undefined {
18	  return typeof value === 'string' && value.trim().length > 0 ? value.trim() : undefined;
19	}
20	
21	function normalizeTags(value: unknown): string[] {
22	  if (Array.isArray(value)) {
23	    return value.map((tag) => String(tag).trim()).filter((tag) => tag.length > 0);
24	  }
25	  if (typeof value === 'string' && value.trim().length > 0) {
26	    return value
27	      .split(',')
28	      .map((tag) => tag.trim())
29	      .filter((tag) => tag.length > 0);
30	  }
31	  return [];
32	}
