39	/** Parses raw markdown (with optional YAML frontmatter) into HTML and structured frontmatter. */
40	export function parseMarkdown(raw: string, fallbackTitle: string): ParsedMarkdown {
41	  const { data, content } = matter(raw);
42	
43	  const frontmatter: PageFrontmatter = {
44	    title: typeof data.title === 'string' && data.title.trim().length > 0 ? data.title.trim() : fallbackTitle,
45	    date: normalizeDate(data.date),
46	    tags: normalizeTags(data.tags),
47	    template: normalizeOptionalString(data.template),
48	    layout: normalizeOptionalString(data.layout),
49	  };
50	
51	  const contentHtml = marked.parse(content, { async: false }) as string;
52	
53	  return { frontmatter, contentHtml };
54	}
