5	export function escapeHtml(value: string): string {
6	  return value
7	    .replace(/&/g, '&amp;')
8	    .replace(/</g, '&lt;')
9	    .replace(/>/g, '&gt;')
10	    .replace(/"/g, '&quot;')
11	    .replace(/'/g, '&#39;');
12	}
13	
14	function readFile(filePath: string): string | undefined {
15	  return fs.existsSync(filePath) ? fs.readFileSync(filePath, 'utf-8') : undefined;
16	}
17	
18	/**
19	 * Thin wrapper around Handlebars for page templates, layouts, and partials.
20	 * Callers pre-escape untrusted values with escapeHtml before handing them in as
21	 * context, so templates always use triple-stache `{{{ }}}` — Handlebars is used
22	 * purely for structure (loops, includes, layout composition), not escaping.
23	 */
24	export class TemplateEngine {
25	  private handlebars: typeof Handlebars;
26	  private templatesDir: string;
27	  private templateCache = new Map<string, HandlebarsTemplateDelegate>();
28	  private layoutCache = new Map<string, HandlebarsTemplateDelegate>();
29	
30	  constructor(templatesDir: string) {
31	    this.templatesDir = templatesDir;
32	    this.handlebars = Handlebars.create();
33	    this.registerPartials();
34	  }
35	
36	  private registerPartials(): void {
37	    const partialsDir = path.join(this.templatesDir, 'partials');
38	    if (!fs.existsSync(partialsDir)) return;
39	    for (const file of fs.readdirSync(partialsDir)) {
40	      if (!file.endsWith('.hbs')) continue;
41	      const name = file.replace(/\.hbs$/, '');
42	      const source = fs.readFileSync(path.join(partialsDir, file), 'utf-8');
43	      this.handlebars.registerPartial(name, source);
44	    }
45	  }
46	
47	  private compile(
48	    cache: Map<string, HandlebarsTemplateDelegate>,
49	    filePath: string,
50	    kind: string
51	  ): HandlebarsTemplateDelegate {
52	    const cached = cache.get(filePath);
53	    if (cached) return cached;
54	    const source = readFile(filePath);
55	    if (source === undefined) {
56	      throw new Error(`${kind} not found: ${filePath}`);
57	    }
58	    const compiled = this.handlebars.compile(source);
59	    cache.set(filePath, compiled);
60	    return compiled;
61	  }
62	
63	  private compileTemplate(name: string): HandlebarsTemplateDelegate {
64	    return this.compile(this.templateCache, path.join(this.templatesDir, `${name}.hbs`), 'Template');
65	  }
66	
67	  private compileLayout(name: string): HandlebarsTemplateDelegate {
68	    return this.compile(this.layoutCache, path.join(this.templatesDir, 'layouts', `${name}.hbs`), 'Layout');
69	  }
70	
71	  /** Renders `templateName` to produce the page body, then wraps it in `layoutName` via {{{body}}}. */
72	  render(
73	    templateName: string,
74	    layoutName: string,
75	    templateContext: Record<string, unknown>,
76	    layoutContext: Record<string, unknown>
77	  ): string {
78	    const body = this.compileTemplate(templateName)(templateContext);
79	    return this.compileLayout(layoutName)({ ...layoutContext, body });
80	  }
81	}
