1	import * as fs from 'fs';
2	import * as http from 'http';
3	import * as path from 'path';
4	import chokidar, { FSWatcher } from 'chokidar';
5	import { WebSocket, WebSocketServer } from 'ws';
6	import { build } from './build';
7	import { BuildOptions } from './types';
8	
9	const LIVE_RELOAD_PATH = '/__livereload';
10	const REBUILD_DEBOUNCE_MS = 100;
11	
12	const LIVE_RELOAD_SCRIPT = `<script>
13	(function () {
14	  var socket = new WebSocket('ws://' + location.host + '${LIVE_RELOAD_PATH}');
15	  socket.addEventListener('message', function (event) {
16	    if (event.data === 'reload') location.reload();
17	  });
18	})();
19	</script>`;
20	
21	const MIME_TYPES: Record<string, string> = {
22	  '.html': 'text/html; charset=utf-8',
23	  '.css': 'text/css; charset=utf-8',
24	  '.js': 'text/javascript; charset=utf-8',
25	  '.json': 'application/json; charset=utf-8',
26	  '.svg': 'image/svg+xml',
27	  '.png': 'image/png',
28	  '.jpg': 'image/jpeg',
29	  '.jpeg': 'image/jpeg',
30	  '.gif': 'image/gif',
31	  '.ico': 'image/x-icon',
32	  '.txt': 'text/plain; charset=utf-8',
33	  '.xml': 'application/xml; charset=utf-8',
34	};
35	
36	export interface ServeOptions extends BuildOptions {
37	  /** Port to listen on. Defaults to 3000. */
38	  port?: number;
39	}
40	
41	export interface ServeHandle {
42	  port: number;
43	  /** Resolves once the file watcher has finished its initial scan and is actively watching for changes. */
44	  ready(): Promise<void>;
45	  close(): Promise<void>;
46	}
47	
48	/** Inserts the live-reload client script just before `</body>`, or appends it if no closing body tag is present. */
49	export function injectLiveReload(html: string): string {
50	  if (/<\/body>/i.test(html)) {
51	    return html.replace(/<\/body>/i, `${LIVE_RELOAD_SCRIPT}</body>`);
52	  }
53	  return html + LIVE_RELOAD_SCRIPT;
54	}
55	
56	/** Resolves a request URL to a file inside outputDir, rejecting attempts to escape it. Returns null if unsafe. */
57	function resolveFilePath(outputDir: string, requestUrl: string): string | null {
58	  const decoded = decodeURIComponent(requestUrl.split('?')[0].split('#')[0]);
59	  const resolvedOutput = path.resolve(outputDir);
60	  const candidate = path.resolve(resolvedOutput, `.${decoded}`);
61	  if (candidate !== resolvedOutput && !candidate.startsWith(resolvedOutput + path.sep)) {
62	    return null;
63	  }
64	  return candidate;
65	}
66	
67	/** Finds the file to serve for a resolved path, trying directory index and .html fallbacks. */
68	function findServableFile(filePath: string): string | null {
69	  if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
70	    filePath = path.join(filePath, 'index.html');
71	  }
72	  if (fs.existsSync(filePath) && fs.statSync(filePath).isFile()) {
73	    return filePath;
74	  }
75	  const withHtml = `${filePath}.html`;
76	  if (fs.existsSync(withHtml) && fs.statSync(withHtml).isFile()) {
77	    return withHtml;
78	  }
79	  return null;
80	}
81	
82	function handleRequest(req: http.IncomingMessage, res: http.ServerResponse, outputDir: string): void {
83	  const requestUrl = req.url ?? '/';
84	  const resolved = resolveFilePath(outputDir, requestUrl);
85	  const filePath = resolved ? findServableFile(resolved) : null;
86	
87	  if (!filePath) {
88	    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
89	    res.end('Not found');
90	    return;
91	  }
92	
93	  const ext = path.extname(filePath).toLowerCase();
94	  const contentType = MIME_TYPES[ext] ?? 'application/octet-stream';
95	
96	  if (ext === '.html') {
97	    const html = fs.readFileSync(filePath, 'utf-8');
98	    res.writeHead(200, { 'Content-Type': contentType });
99	    res.end(injectLiveReload(html));
100	    return;
101	  }
102	
103	  res.writeHead(200, { 'Content-Type': contentType });
104	  res.end(fs.readFileSync(filePath));
105	}
106	
107	/** Starts a live-reload dev server: serves outputDir over HTTP, rebuilds on content/template changes, and pushes reloads over WebSocket. */
108	export function serve(options: ServeOptions): ServeHandle {
109	  const { contentDir, outputDir, templatesDir, siteTitle } = options;
110	  const port = options.port ?? 3000;
111	
112	  const runBuild = (): void => {
113	    build({ contentDir, outputDir, templatesDir, siteTitle });
114	  };
115	
116	  runBuild();
117	
118	  const wss = new WebSocketServer({ noServer: true });
119	
120	  const server = http.createServer((req, res) => handleRequest(req, res, outputDir));
121	
122	  server.on('upgrade', (req, socket, head) => {
123	    if (req.url === LIVE_RELOAD_PATH) {
124	      wss.handleUpgrade(req, socket, head, (ws) => wss.emit('connection', ws, req));
125	    } else {
126	      socket.destroy();
127	    }
128	  });
129	
130	  function broadcastReload(): void {
131	    for (const client of wss.clients) {
132	      if (client.readyState === WebSocket.OPEN) {
133	        client.send('reload');
134	      }
135	    }
136	  }
137	
138	  let rebuildTimer: NodeJS.Timeout | undefined;
139	  function scheduleRebuild(): void {
140	    if (rebuildTimer) clearTimeout(rebuildTimer);
141	    rebuildTimer = setTimeout(() => {
142	      try {
143	        runBuild();
144	        broadcastReload();
145	      } catch (error) {
146	        const message = error instanceof Error ? error.message : String(error);
147	        // eslint-disable-next-line no-console
148	        console.error(`ssg: rebuild failed: ${message}`);
149	      }
150	    }, REBUILD_DEBOUNCE_MS);
151	  }
152	
153	  const watchPaths = Array.from(new Set([contentDir, templatesDir ?? './templates'])).filter((dir) =>
154	    fs.existsSync(dir)
155	  );
156	  const watcher: FSWatcher = chokidar.watch(watchPaths, { ignoreInitial: true });
157	  watcher.on('all', () => scheduleRebuild());
158	  const watcherReady = new Promise<void>((resolve) => watcher.once('ready', resolve));
159	
160	  server.listen(port);
161	
162	  return {
163	    get port(): number {
164	      const address = server.address();
165	      return typeof address === 'object' && address !== null ? address.port : port;
166	    },
167	    ready(): Promise<void> {
168	      return watcherReady;
169	    },
170	    close(): Promise<void> {
171	      if (rebuildTimer) clearTimeout(rebuildTimer);
172	      for (const client of wss.clients) {
173	        client.terminate();
174	      }
175	      return watcher.close().then(
176	        () =>
177	          new Promise((resolve, reject) => {
178	            wss.close(() => {
179	              server.closeAllConnections();
180	              server.close((error) => (error ? reject(error) : resolve()));
181	            });
182	          })
183	      );
184	    },
185	  };
186	}
