1	import { build } from './build';
2	import { serve, ServeHandle } from './serve';
3	
4	export interface CliArgs {
5	  command: string;
6	  contentDir: string;
7	  outputDir: string;
8	  templatesDir?: string;
9	  port?: number;
10	}
11	
12	const DEFAULT_CONTENT_DIR = './content';
13	const DEFAULT_OUTPUT_DIR = './dist';
14	const DEFAULT_PORT = 3000;
15	
16	export function parseArgs(argv: string[]): CliArgs {
17	  const [command = 'build', ...rest] = argv;
18	  let contentDir = DEFAULT_CONTENT_DIR;
19	  let outputDir = DEFAULT_OUTPUT_DIR;
20	  let templatesDir: string | undefined;
21	  let port: number | undefined;
22	
23	  for (let i = 0; i < rest.length; i++) {
24	    const arg = rest[i];
25	    if (arg === '--content') {
26	      const value = rest[i + 1];
27	      if (!value) throw new Error('--content requires a directory argument');
28	      contentDir = value;
29	      i++;
30	    } else if (arg === '--output') {
31	      const value = rest[i + 1];
32	      if (!value) throw new Error('--output requires a directory argument');
33	      outputDir = value;
34	      i++;
35	    } else if (arg === '--templates') {
36	      const value = rest[i + 1];
37	      if (!value) throw new Error('--templates requires a directory argument');
38	      templatesDir = value;
39	      i++;
40	    } else if (arg === '--port') {
41	      const value = rest[i + 1];
42	      if (!value) throw new Error('--port requires a numeric argument');
43	      const parsed = Number(value);
44	      if (!Number.isInteger(parsed) || parsed < 0) throw new Error('--port requires a numeric argument');
45	      port = parsed;
46	      i++;
47	    } else {
48	      throw new Error(`Unknown argument: ${arg}`);
49	    }
50	  }
51	
52	  return {
53	    command,
54	    contentDir,
55	    outputDir,
56	    ...(templatesDir !== undefined ? { templatesDir } : {}),
57	    ...(port !== undefined ? { port } : {}),
58	  };
59	}
