61	export function run(argv: string[]): ServeHandle | void {
62	  const args = parseArgs(argv);
63	
64	  if (args.command === 'build') {
65	    const result = build({ contentDir: args.contentDir, outputDir: args.outputDir, templatesDir: args.templatesDir });
